package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string           // PIC X len=1 = "N"
var WsC decimal.Decimal        // PIC S9(3)V99 len=5 = 0
var WsFreeze int64             // PIC 99 len=2 = 0
var WsCount int64              // PIC 99 len=2 = 0
var WsFEd string               // PIC ZZ9.9 len=5
var WsCEd string               // PIC -ZZ9.99 len=7
var TempRecData TempRec

var tempFile *os.File
var tempReader *bufio.Reader
var inputDone bool

func formatZZ9_9(v decimal.Decimal) string {
	return formatEdited(v, "ZZ9.9")
}
func formatMinusZZ9_99(v decimal.Decimal) string {
	return formatEdited(v, "-ZZ9.99")
}

// generic numeric-edited formatter for pictures containing Z,9,',','.', and leading '-'
func formatEdited(v decimal.Decimal, pic string) string {
	// detect leading sign
	hasMinus := false
	if len(pic) > 0 && pic[0] == '-' {
		hasMinus = true
		pic = pic[1:]
	}
	// find decimal point
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	fracDigits := len(fracPic)

	// scale value to fracDigits trunc? For display, value already has correct scale; just format rounding already done.
	// We need to split integer and fractional parts.
	// Use Abs for formatting, sign handled separately.
	neg := v.Sign() < 0
	av := v.Abs()

	// Get integer part and fractional part with correct scale
	// Ensure av has scale fracDigits (truncate/pad)
	// Use string representation
	// Shift to get integer and fraction
	// We'll format by getting coefficient
	// Easier: quantized = av.Truncate(int32(fracDigits)) but av already rounded; just extract.
	// Use av.StringFixed to get padded
	s := av.StringFixed(int32(fracDigits))

	// s like "123.45" or "0.00" etc
	var intStr, fracStr string
	if fracDigits > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
	} else {
		intStr = s
		// remove any dot part if present
		if idx := strings.Index(intStr, "."); idx >= 0 {
			intStr = intStr[:idx]
		}
	}

	// Handle overflow of integer part: keep low-order digits that fit
	// intPic capacity = number of digit placeholders (Z or 9 or , counted as digit position? commas occupy a position but are digit placeholder)
	// For counting capacity, each 'Z','9' is a digit slot. Comma is also a slot that corresponds to digit (when not suppressed).
	// So capacity = count of Z,9 in intPic
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	if len(intStr) > intSlots {
		intStr = intStr[len(intStr)-intSlots:]
	}
	// Pad intStr on left with zeros to intSlots
	if len(intStr) < intSlots {
		intStr = strings.Repeat("0", intSlots-len(intStr)) + intStr
	}

	// Now build intPart according to intPic from right to left
	// intPic may contain commas
	// We map digit slots to intStr digits
	intResult := make([]byte, len(intPic))
	// index into intStr
	dIdx := len(intStr) - 1
	// Track whether any non-zero digit has been encountered (for Z suppression)
	// Need to know if the whole integer part is zero for suppression logic
	// For Z suppression, we suppress leading zeros, replacing Z positions and associated commas with spaces.
	// Determine suppression: scan from left; while digit is '0' and the remaining significant part is zero?
	// Simpler: find first non-zero in intStr
	firstNonZero := -1
	for i, ch := range intStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	// If all zeros, then all Z positions are suppressed (replace with space), but the rightmost 9 must still show 0.
	// General rule: Z positions that are leading zeros become spaces. Once a non-zero is encountered, or we reach a '9' position, stop suppressing.
	// Also commas inside suppressed zone become spaces.
	suppressing := true
	// We need to know for each slot whether it is still in leading zero zone
	// Iterate intPic left to right, consuming digit slots
	slotIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			digit := intStr[slotIdx]
			isLeadingZero := suppressing && digit == '0' && !(ch == '9' && slotIdx == intSlots-1 && firstNonZero == -1) // keep last 9 even if zero?
			// Actually to handle all zeros: we want all Z to be spaces, and the final 9 to be '0'
			// Determine if this slot is beyond firstNonZero: if firstNonZero == -1 (all zero) then still leading.
			// For Z slots when all zero, suppress.
			// For 9 slot when all zero, do not suppress (show 0)
			if ch == '9' {
				// '9' always prints digit, and ends suppression for following? But suppression ends when we output a non-space digit.
				// If it's the last mandatory digit and all zero, we print 0
				// If there are multiple 9s, they always print
				intResult[i] = digit
				suppressing = false
			} else { // Z
				if firstNonZero == -1 {
					// all zeros -> suppress this Z
					intResult[i] = ' '
				} else if slotIdx < firstNonZero {
					intResult[i] = ' '
				} else {
					intResult[i] = digit
					suppressing = false
				}
			}
			slotIdx++
			// if we just printed a non-space, suppression ends for comma handling? commas already handled by suppression flag at that point.
			// But we need to keep suppressing flag false after first non-suppressed digit
			if intResult[i] != ' ' {
				suppressing = false
			}
		} else if ch == ',' {
			if suppressing {
				intResult[i] = ' '
			} else {
				intResult[i] = ','
			}
		} else {
			intResult[i] = byte(ch)
		}
	}

	// Build final string
	var out string
	if hasMinus {
		signChar := ' '
		if neg {
			signChar = '-'
		}
		out = string(signChar) + string(intResult)
	} else {
		out = string(intResult)
	}
	if fracDigits > 0 {
		out += "." + fracStr
	}
	return out
}

func formatIntZeroPad(v int64, width int) string {
	s := fmt.Sprintf("%d", v)
	if len(s) > width {
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseTempRec(line string) TempRec {
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	var r TempRec
	r.TcSensor = line[0:4]
	raw := line[4:8]
	raw = strings.TrimSpace(raw)
	if raw == "" {
		raw = "0"
	}
	// PIC 9(3)V9 => 1 decimal place, digits only
	// raw may contain spaces? But input is digits; handle.
	// Remove any non-digit (should not happen)
	digits := ""
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		digits = "0"
	}
	// Build decimal with scale 1
	n, _ := decimal.NewFromString(digits)
	// digits represent value *10
	d := decimal.NewFromBigInt(n.Coefficient(), -1)
	// Actually NewFromString already integer; we need shift -1
	// Use decimal.New with exponent -1
	// Simpler: use decimal.New(n.IntPart(), -1) but handle big
	// Do via Shift
	val := decimal.NewFromStringNoCheck(digits)
	_ = d
	val2 := val.Shift(-1)
	r.TcF = val2
	return r
}

func MAIN_PARA() {
	OPEN_INPUT()
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	CLOSE_FILE()
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	// WS-COUNT and WS-FREEZE are PIC 99 -> zero padded width 2
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatIntZeroPad(WsCount, 2), formatIntZeroPad(WsFreeze, 2))
}

func OPEN_INPUT() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	tempFile = f
	tempReader = bufio.NewReader(f)
}

func CLOSE_FILE() {
	if tempFile != nil {
		tempFile.Close()
	}
}

func READ_PARA() {
	line, err := tempReader.ReadString('\n')
	if err != nil {
		// EOF - check if we got partial line
		if len(line) == 0 {
			WsEofFlag = "Y"
			inputDone = true
			return
		}
		// partial last line without newline -> process it
		line = strings.TrimRight(line, "\r\n")
		TempRecData = parseTempRec(line)
		// Next read will be EOF
		// To mimic COBOL, we need to return this record now, and next call hits EOF
		// So we need to push back EOF state: we have consumed line, next call should be EOF
		// We handle by setting a flag that next read is EOF; but we already have data
		// Use a one-record buffer: we succeeded, so don't mark done yet, but arrange next read to be done
		// Implement via a pending EOF flag
		pendingEOF = true
		WsEofFlag = "N"
		inputDone = false
		return
	}
	line = strings.TrimRight(line, "\r\n")
	TempRecData = parseTempRec(line)
	WsEofFlag = "N"
	inputDone = false
}

var pendingEOF bool

func READ_PARA_WRAPPER() {
	if pendingEOF {
		// previous partial read consumed, now report EOF on next call
		// But we already consumed that record; the next read should be EOF
		// So if pendingEOF true, we need to treat next invocation as EOF, unless we already delivered record
		// The pendingEOF indicates that the last successful read was the final line without newline;
		// the next call should signal EOF.
		// To avoid double delivery, we track whether we have just delivered pending record
		// This wrapper is not used; instead READ_PARA handles directly
	}
	READ_PARA()
}

// Override READ_PARA to handle pendingEOF correctly
func init() {
	// Replace READ_PARA with version that respects pending
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	// Rounded to scale of WS-C = 2 decimals
	tmp := TempRecData.TcF.Sub(decimal.NewFromInt(32)).Mul(decimal.NewFromInt(5)).Div(decimal.NewFromInt(9))
	// Use Div but we want exact; Div is okay but spec says avoid Div; we can multiply then divide via decimal division which is okay for small numbers
	// Do rounding half away from zero to 2 decimals
	rounded := tmp.Round(2)
	// Store into S9(3)V99 with overflow truncation high-order digits silently dropped
	WsC = storeSigned(rounded, 3, 2)

	if WsC.Sign() < 0 {
		WsFreeze++
		// PIC 99 overflow truncation handled on display? But count keeps increasing; apply wrap for storage
		WsFreeze = truncInt(WsFreeze, 2)
	}
	WsCount++
	WsCount = truncInt(WsCount, 2)

	WsFEd = formatEdited(TempRecData.TcF, "ZZ9.9")
	WsCEd = formatEdited(WsC, "-ZZ9.99")

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", padRight(TempRecData.TcSensor, 4), WsFEd, WsCEd)

	// PERFORM READ-PARA
	// Need to handle pendingEOF case
	if pendingEOF {
		pendingEOF = false
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	READ_PARA()
}

func storeSigned(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// Keep only low-order integer digits that fit (high-order truncation)
	// For S9(3)V99: intDigits=3, scale=2
	// Truncate high order integer digits: e.g., 1234.56 with 3 int digits -> 234.56
	// Preserve sign
	neg := v.Sign() < 0
	av := v.Abs()
	// Extract integer and fractional parts
	// Get as string with fixed scale
	s := av.StringFixed(int32(scale))
	parts := strings.SplitN(s, ".", 2)
	intPart := parts[0]
	fracPart := ""
	if len(parts) > 1 {
		fracPart = parts[1]
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	// rebuild
	var rebuilt decimal.Decimal
	if scale > 0 {
		combined := intPart + fracPart
		if combined == "" {
			combined = "0"
		}
		d, _ := decimal.NewFromString(combined)
		rebuilt = d.Shift(int32(-scale))
	} else {
		d, _ := decimal.NewFromString(intPart)
		rebuilt = d
	}
	if neg {
		rebuilt = rebuilt.Neg()
	}
	return rebuilt
}

func truncInt(v int64, width int) int64 {
	// PIC 99 keeps low-order digits
	mod := int64(1)
	for i := 0; i < width; i++ {
		mod *= 10
	}
	if v >= mod || v < 0 {
		// keep low-order digits; for positive counts just mod
		v = v % mod
		if v < 0 {
			v += mod
		}
	}
	return v
}

func main() {
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0
	MAIN_PARA()
}

